import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Механизм открытости ресурсов культивации","description":"","frontmatter":{},"headers":[],"relativePath":"ru/18-修炼资源开放机制.md","filePath":"ru/18-修炼资源开放机制.md","lastUpdated":1789183869000}'),d={name:"ru/18-修炼资源开放机制.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="механизм-открытости-ресурсов-культивации" tabindex="-1">Механизм открытости ресурсов культивации <a class="header-anchor" href="#механизм-открытости-ресурсов-культивации" aria-label="Permalink to &quot;Механизм открытости ресурсов культивации&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>18</td></tr><tr><td>Модуль</td><td>Космические законы и системы культивации</td></tr><tr><td>Ключевые слова</td><td>Открытость ресурсов, Ресурсы культивации, Механизм распределения, Антимонополия, Справедливость ресурсов</td></tr></tbody></table><h2 id="i-контекст-и-значение-механизма-открытости-ресурсов-культивации" tabindex="-1">I. Контекст и значение механизма открытости ресурсов культивации <a class="header-anchor" href="#i-контекст-и-значение-механизма-открытости-ресурсов-культивации" aria-label="Permalink to &quot;I. Контекст и значение механизма открытости ресурсов культивации&quot;">​</a></h2><p>В эпоху хищничества ресурсы культивации были центральнейшим объектом борьбы. Духовные жилы, лекарственные поля, энергетические рудные жилы, небесные сокровища, секретные миры культивации монополизировались немногими сильными и сектами, а низы почти не могли получить нормальные ресурсы. Монополия не только закрепила классовое расслоение, но и породила бесчисленные войны и резни из-за ресурсов. Монополия — экономическая основа хищнической системы: пока ресурсы монополизированы немногими, «Путь для Каждого» — лишь пустые слова.</p><p>После установления Симбиотической Цивилизации Якоря «открытость ресурсов культивации» стала одной из центральнейших институциональных реформ. Центральная цель механизма: сломать монополию, обеспечить каждому существу базовые ресурсы, и через механизм «Больше Труда — Больше Награды» стимулировать эффективное использование и непрерывное создание ресурсов. Открытость — не «уравнительное распределение», а «справедливый доступ»: при гарантии базовых нужд распределение связано с вкладом индивида, при строгом запрете любой монополии.</p><p>Значение механизма: он выкорчёвывает почву хищничества из экономического основания, даёт материальную гарантию подлинной популяризации Трёхсот Систем, ресурсную поддержку социальной цели «Путь для Каждого» и справедливый старт общему прогрессу Десяти Тысяч Рас.</p><h2 id="ii-классификация-и-уровни-ресурсов-культивации" tabindex="-1">II. Классификация и уровни ресурсов культивации <a class="header-anchor" href="#ii-классификация-и-уровни-ресурсов-культивации" aria-label="Permalink to &quot;II. Классификация и уровни ресурсов культивации&quot;">​</a></h2><h3 id="_2-1-классификация-ресурсов" tabindex="-1">2.1 Классификация ресурсов <a class="header-anchor" href="#_2-1-классификация-ресурсов" aria-label="Permalink to &quot;2.1 Классификация ресурсов&quot;">​</a></h3><p>Ресурсы в Хэн Юаньчжоу по природе и применению делятся на категории:</p><table tabindex="0"><thead><tr><th>Категория</th><th>Содержание</th><th>Основное применение</th></tr></thead><tbody><tr><td>Энергетические</td><td>Духовные жилы, энергорудные жилы, кристаллы ци, фрагменты изначальной энергии</td><td>Энергетический вход культивации</td></tr><tr><td>Медикаментозные</td><td>Духовные травы, бессмертные травы, алхимические материалы, готовые пилюли</td><td>Содействие культивации, лечение, прорывы барьеров</td></tr><tr><td>Снаряжение</td><td>Артефакты, приборы законов, устройства умножения, пространственное оборудование</td><td>Повышение эффективности, помощь управлению законами</td></tr><tr><td>Пространственные</td><td>Секретные миры, зоны концентрации ци, залы постижения законов, Изолированное Пространство</td><td>Особая среда культивации</td></tr><tr><td>Знаниевые</td><td>Техники, опыт, материалы исследований законов, технические документы</td><td>Теоретическое и методическое руководство</td></tr><tr><td>Биологические</td><td>Духовные звери, духовные растения, контрактные существа, симбионты</td><td>Помощь, симбиотическая циркуляция, особые способности</td></tr><tr><td>Плановые</td><td>Неосвоенные планы, права на каналы, фрагменты ядер планов</td><td>Крупномасштабное пространство культивации и развития</td></tr></tbody></table><h3 id="_2-2-уровни-ресурсов" tabindex="-1">2.2 Уровни ресурсов <a class="header-anchor" href="#_2-2-уровни-ресурсов" aria-label="Permalink to &quot;2.2 Уровни ресурсов&quot;">​</a></h3><p>Все ресурсы по редкости и ценности делятся на пять уровней:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Название</th><th>Редкость</th><th>Способ распределения</th></tr></thead><tbody><tr><td>Первый</td><td>Обычные</td><td>Широко распространены, запасы обильны</td><td>Свободно или по низкой цене</td></tr><tr><td>Второй</td><td>Хорошие</td><td>Довольно часты, запасы умеренны</td><td>Базовая выдача + обмен на вклад</td></tr><tr><td>Третий</td><td>Редкие</td><td>Довольно редки, запасы ограничены</td><td>Обмен на вклад + одобрение заявки</td></tr><tr><td>Четвёртый</td><td>Эпические</td><td>Очень редки, запасов крайне мало</td><td>Конкурсное распределение + приоритет проектам уровня цивилизации</td></tr><tr><td>Пятый</td><td>Легендарные</td><td>Чрезвычайно редки, почти исчезли</td><td>Специальное распределение высшим органом цивилизации</td></tr></tbody></table><h2 id="iii-центральные-принципы-открытости-ресурсов" tabindex="-1">III. Центральные принципы открытости ресурсов <a class="header-anchor" href="#iii-центральные-принципы-открытости-ресурсов" aria-label="Permalink to &quot;III. Центральные принципы открытости ресурсов&quot;">​</a></h2><h3 id="_3-1-принцип-базовои-гарантии" tabindex="-1">3.1 Принцип базовой гарантии <a class="header-anchor" href="#_3-1-принцип-базовои-гарантии" aria-label="Permalink to &quot;3.1 Принцип базовой гарантии&quot;">​</a></h3><p>Каждое существо имеет право на ресурсы первого и второго уровней для базовой культивации. Ресурсы базовой гарантии выдаются бесплатно или дёшево через «систему Путь для Каждого», без порогов и дискриминации. Стандарт периодически корректируется Парламентом Республики Десяти Тысяч Рас по состоянию ресурсов и этапу развития, обеспечивая соответствие гарантии несущей способности цивилизации.</p><h3 id="_3-2-принцип-«больше-труда-—-больше-награды»" tabindex="-1">3.2 Принцип «Больше Труда — Больше Награды» <a class="header-anchor" href="#_3-2-принцип-«больше-труда-—-больше-награды»" aria-label="Permalink to &quot;3.2 Принцип «Больше Труда — Больше Награды»&quot;">​</a></h3><p>Выше базовой гарантии распределение ресурсов третьего уровня и выше основано на величине вклада индивида в симбиотическую сеть. Больше вклад — больше и выше ресурсы. Принцип стимулирует практиков поднимать уровни и вносить больший вклад, а также направляет ресурсы к тем, кто использует их эффективнее всего.</p><h3 id="_3-3-принцип-антимонополии" tabindex="-1">3.3 Принцип антимонополии <a class="header-anchor" href="#_3-3-принцип-антимонополии" aria-label="Permalink to &quot;3.3 Принцип антимонополии&quot;">​</a></h3><p>Строго запрещена монополизация ресурсов любым индивидом, организацией, расой. Меры:</p><ul><li>Ресурсы третьего уровня и выше у одного индивида или организации — не более 1% общих запасов цивилизации</li><li>Запрет спекулятивного накопления: в периоды дефицита нельзя злонамеренно копить и взвинчивать цены</li><li>Запрет исключительного владения: общественные ресурсы (общественные жилы, секретные миры) не могут принадлежать частным лицам</li><li>Нарушения караются Судом Якорей: конфискация ресурсов, обнуление вклада, ограничение прав культивации</li></ul><h3 id="_3-4-принцип-устоичивого-использования" tabindex="-1">3.4 Принцип устойчивого использования <a class="header-anchor" href="#_3-4-принцип-устоичивого-использования" aria-label="Permalink to &quot;3.4 Принцип устойчивого использования&quot;">​</a></h3><p>Освоение и использование ресурсов должны быть устойчивыми; хищническая добыча запрещена. Требования:</p><ul><li>Скорость освоения не выше скорости естественного восстановления (для невозобновляемых — планы замены)</li><li>Экологическая оценка воздействия перед освоением, недопущение необратимого ущерба</li><li>Для исчезающих ресурсов — запреты или ограничения добычи, защита восстановления</li><li>Поощрение искусственного выращивания и синтеза редких ресурсов технологиями (инженерия законов, умножение), снижение зависимости от природы</li></ul><h3 id="_3-5-принцип-открытости-и-прозрачности" tabindex="-1">3.5 Принцип открытости и прозрачности <a class="header-anchor" href="#_3-5-принцип-открытости-и-прозрачности" aria-label="Permalink to &quot;3.5 Принцип открытости и прозрачности&quot;">​</a></h3><p>Процесс распределения открыт и прозрачен, под надзором всех существ:</p><ul><li>Запасы, распределение, освоение общественных ресурсов регулярно публикуются</li><li>Стандарты, процессы, результаты распределения открыты и проверяемы</li><li>Механизм обжалования: несогласные могут просить пересмотр</li><li>«Комитет справедливости ресурсов» при Суде Якорей следит за справедливостью и законностью</li></ul><h2 id="iv-конкретные-механизмы-открытости-ресурсов" tabindex="-1">IV. Конкретные механизмы открытости ресурсов <a class="header-anchor" href="#iv-конкретные-механизмы-открытости-ресурсов" aria-label="Permalink to &quot;IV. Конкретные механизмы открытости ресурсов&quot;">​</a></h2><h3 id="_4-1-механизм-подряда-связанного-с-результатом" tabindex="-1">4.1 Механизм подряда, связанного с результатом <a class="header-anchor" href="#_4-1-механизм-подряда-связанного-с-результатом" aria-label="Permalink to &quot;4.1 Механизм подряда, связанного с результатом&quot;">​</a></h3><p>Подряд — центральная институциональная конструкция; базовый порядок описан в документе «Принципы распределения: Больше Труда — Больше Награды». Конкретные применения:</p><ul><li><strong>Подряд духовных жил</strong>: общественные жилы передаются группам практиков или общинам рас; подрядчик обслуживает и устойчиво осваивает жилу, получая долю продукции</li><li><strong>Подряд лекарственных полей</strong>: поля передаются практикам с умением выращивать; подрядчик сажает и ухаживает, урожай делится пропорционально</li><li><strong>Управление секретными мирами</strong>: общественные миры доверяются профессиональным командам; пользователи платят разумную плату</li><li><strong>Разведка ресурсов</strong>: поощрение разведки неосвоенных зон; первооткрыватели имеют приоритетное право подряда</li></ul><h3 id="_4-2-механизм-обмена-на-величину-вклада" tabindex="-1">4.2 Механизм обмена на величину вклада <a class="header-anchor" href="#_4-2-механизм-обмена-на-величину-вклада" aria-label="Permalink to &quot;4.2 Механизм обмена на величину вклада&quot;">​</a></h3><p>Цивилизация создала единую «систему обмена на величину вклада»: практики накапливают вклад, внося вклад в сеть, и обменивают на ресурсы:</p><ul><li>Пути накопления: прогресс культивации, обмен знаниями, технологические инновации, общественная служба, экологическое восстановление, охрана цивилизации</li><li>«Ясные цены»: у каждого ресурса чёткая цена, динамически корректируемая по редкости и спросу</li><li>Функция «аванса»: перспективные практики могут авансировать вклад, погашая будущими достижениями</li><li>Система связана с сетью якорей в реальном времени, обеспечивая надёжность</li></ul><h3 id="_4-3-механизм-свободного-доступа-к-общественным-ресурсам" tabindex="-1">4.3 Механизм свободного доступа к общественным ресурсам <a class="header-anchor" href="#_4-3-механизм-свободного-доступа-к-общественным-ресурсам" aria-label="Permalink to &quot;4.3 Механизм свободного доступа к общественным ресурсам&quot;">​</a></h3><p>Свободно открыты всем существам:</p><ul><li><strong>Знаниевые</strong>: базовые техники Трёхсот Систем, общественный опыт, базовые материалы исследований законов</li><li><strong>Энергия первого уровня</strong>: базовое ци, обычные кристаллы и прочие распространённые низшие ресурсы</li><li><strong>Общественные пространства</strong>: общие залы культивации, залы постижения базовых законов, обычные Изолированные Пространства</li><li><strong>Базовая медицина</strong>: базовые техники лечения, обычные пилюли, базовые услуги реабилитации</li><li><strong>Базовое образование</strong>: базовые курсы, вводное наставничество, пользование общим оборудованием</li></ul><h3 id="_4-4-механизм-адресного-распределения-особых-ресурсов" tabindex="-1">4.4 Механизм адресного распределения особых ресурсов <a class="header-anchor" href="#_4-4-механизм-адресного-распределения-особых-ресурсов" aria-label="Permalink to &quot;4.4 Механизм адресного распределения особых ресурсов&quot;">​</a></h3><p>Для редких ресурсов четвёртого и пятого уровней — «адресное распределение»:</p><ul><li>Приоритет ключевым проектам уровня цивилизации (строительство якорей, освоение планов, технические прорывы)</li><li>Индивиды с особыми нуждами (ресурсы для прорыва, редкие лекарства) — через заявку и одобрение</li><li>Планы составляются «Комитетом распределения ресурсов» при Парламенте, исполняются после одобрения</li><li>Результаты публикуются и поднадзорны</li></ul><h2 id="v-создание-ресурсов-и-устоичивое-развитие" tabindex="-1">V. Создание ресурсов и устойчивое развитие <a class="header-anchor" href="#v-создание-ресурсов-и-устоичивое-развитие" aria-label="Permalink to &quot;V. Создание ресурсов и устойчивое развитие&quot;">​</a></h2><p>Открытость — не только «распределение существующего», но и «создание прироста». Цивилизация поощряет искусственное создание и устойчивое освоение:</p><h3 id="_5-1-искусственное-выращивание" tabindex="-1">5.1 Искусственное выращивание <a class="header-anchor" href="#_5-1-искусственное-выращивание" aria-label="Permalink to &quot;5.1 Искусственное выращивание&quot;">​</a></h3><ul><li><strong>Искусственное выращивание духовных трав</strong>: инженерия законов, снижение зависимости от диких трав</li><li><strong>Искусственное производство энергии</strong>: устройства превращения материи, генераторы резонанса законов</li><li><strong>Искусственное разведение духовных зверей</strong>: базы разведения, защита диких популяций</li><li><strong>Искусственное строительство секретных миров</strong>: технология пространственного закона, рост предложения пространств</li></ul><h3 id="_5-2-повторное-использование" tabindex="-1">5.2 Повторное использование <a class="header-anchor" href="#_5-2-повторное-использование" aria-label="Permalink to &quot;5.2 Повторное использование&quot;">​</a></h3><ul><li><strong>Рекуперация энергии</strong>: системы сбора потерянной и рассеянной энергии</li><li><strong>Обработка алхимических остатков</strong>: вторичная экстракция, рост использования</li><li><strong>Переработка снаряжения</strong>: рециклинг и переделка списанного</li><li><strong>Цикличное использование пространств</strong>: очистка и повторное использование Изолированных Пространств</li></ul><h3 id="_5-3-технология-замены-ресурсов" tabindex="-1">5.3 Технология замены ресурсов <a class="header-anchor" href="#_5-3-технология-замены-ресурсов" aria-label="Permalink to &quot;5.3 Технология замены ресурсов&quot;">​</a></h3><ul><li>Разработка заменителей редких ресурсов: «замена редкого обычным»</li><li>Для невозобновляемых легендарных — строгие планы охраны и роста вложений в замену</li><li>«Фонд разработки технологий замены ресурсов» для финансирования исследований</li></ul><h2 id="vi-надзор-и-защита-открытости-ресурсов" tabindex="-1">VI. Надзор и защита открытости ресурсов <a class="header-anchor" href="#vi-надзор-и-защита-открытости-ресурсов" aria-label="Permalink to &quot;VI. Надзор и защита открытости ресурсов&quot;">​</a></h2><h3 id="_6-1-механизмы-надзора" tabindex="-1">6.1 Механизмы надзора <a class="header-anchor" href="#_6-1-механизмы-надзора" aria-label="Permalink to &quot;6.1 Механизмы надзора&quot;">​</a></h3><ul><li><strong>Мониторинг сети якорей в реальном времени</strong>: разработка, распределение, использование общественных ресурсов под наблюдением; аномалии — сигнал</li><li><strong>Комитет справедливости ресурсов</strong>: надзор за справедливостью и законностью, приём жалоб</li><li><strong>Общественный надзор</strong>: поощрение сообщений о нарушениях</li><li><strong>Регулярный аудит</strong>: ежегодный независимый аудит органов управления, публикация результатов</li></ul><h3 id="_6-2-механизмы-защиты" tabindex="-1">6.2 Механизмы защиты <a class="header-anchor" href="#_6-2-механизмы-защиты" aria-label="Permalink to &quot;6.2 Механизмы защиты&quot;">​</a></h3><ul><li><strong>Обжалование распределения</strong>: пересмотр в Комитете справедливости</li><li><strong>Арбитраж споров о ресурсах</strong>: Суд Якорей, решения имеют юридическую силу</li><li><strong>Возмещение ущерба</strong>: иски о монополии и разграблении ресурсов, требование компенсации</li><li><strong>Экстренная помощь</strong>: при катастрофах и войнах — экстренное перераспределение для пострадавших</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Механизм открытости ресурсов культивации — ядро экономической системы Симбиотической Цивилизации Якоря. Через пять принципов — «базовая гарантия + Больше Труда — Больше Награды + антимонополия + устойчивость + открытость и прозрачность» — создана справедливая, эффективная, устойчивая система распределения. Конечная цель — не одинаковое количество ресурсов для всех, а равная возможность получения, направление ресурсов туда, где создаётся наибольшая ценность, и непрерывный рост совокупных ресурсов цивилизации в устойчивых условиях. Когда ресурсы культивации перестанут быть частной собственностью немногих и станут общественным достоянием Десяти Тысяч Рас, приумножаемым циркуляцией, идеал «Путь для Каждого» по-настоящему пустит корни, а цель общего прогресса Десяти Тысяч Рас действительно реализуется.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Принципы распределения: Больше Труда — Больше Награды)</li><li>08-人人有路保障体系 (Система «Путь для Каждого»)</li><li>22-资源分配联产承包机制 (Механизм подряда распределения ресурсов)</li></ul>',57)])])}const _=a(d,[["render",e]]);export{c as __pageData,_ as default};
